/* APLUS P6 English Prelim — Comprehension Open-Ended Module V2
   Rebuilds Q66–Q75 as coherent linked comprehension questions.
*/
(function(){'use strict';
const VERSION='PSLE_COMPREHENSION_OE_V2.2',GNAME='APLUS_P6_PSLE_PAPER2_GENERATION_V1';
const rnd=seed=>{let x=(seed>>>0)||1;return()=>{x^=x<<13;x^=x>>>17;return(x>>>0)/4294967296}};
const sh=(a,r)=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const get=n=>Array.isArray(window[n])?window[n]:[];
const dedupe=(a,k)=>{const m=new Map();a.forEach(x=>{if(x){const z=k(x);if(z&&!m.has(z))m.set(z,x)}});return[...m.values()]};
function registry(){return{passages:dedupe([].concat(get('APLUS_AI_DB_V1_P6_COMPREHENSION_PASSAGE_SETS_BATCH01'),get('APLUS_AI_DB_V1_P6_COMPREHENSION_PASSAGE_SETS_BATCH02')),x=>String(x.passageId||x.id||x.title||'')),comp:dedupe([].concat(get('APLUS_AI_DB_V1_P6_COMPREHENSION_QUESTION_BANK'),get('APLUS_AI_DB_V1_P6_COMPREHENSION_EXPANSION_BATCH02')),x=>String(x.id||x.question||''))}}
function answerOf(q){if(q==null)return '';if(typeof q.answer==='number'&&Array.isArray(q.options))return q.options[q.answer]??'';if(Array.isArray(q.answer))return q.answer.join('; ');return String(q.answer??'')}
function normalize(q,p,pid,i){const a=answerOf(q);if(!q.question||!a)return null;const skill=String(q.skill||q.type||'comprehension').replace(/_/g,' ');let question=String(q.question).trim();const l=question.toLowerCase();if((l.includes('what does')||l.includes('what is meant by'))&&!/own words/i.test(question))question+=' Answer in your own words.';else if(/what can we infer|why did|why was|what lesson|how did|main idea|mainly about/i.test(question)&&!/complete sentence/i.test(question))question+=' Answer in a complete sentence.';return{type:'oe',responseType:'open-ended',marks:2,section:'comprehension',passage:p,passageSetId:String(pid||''),question,answer:a,acceptedPatterns:[a,...(Array.isArray(q.acceptedPatterns)?q.acceptedPatterns:[])],explanation:q.explanation||'',skill,difficulty:Number(q.difficulty)||3,sourceDatabase:'APLUS P6 Comprehension Passage Sets — PSLE OE DNA',sourceRecordId:String(q.id||i),generationLayer:VERSION}}
function build(seed){const r=rnd(seed),c=sh(registry().passages,r).filter(p=>String(p.passage||p.text||'').trim().length>=250&&Array.isArray(p.questions)&&p.questions.length>=5),out=[];c.slice(0,2).forEach(p=>p.questions.slice(0,5).forEach((q,i)=>{const x=normalize(q,String(p.passage||p.text||'').trim(),p.passageId||p.id||p.title,i);if(x)out.push(x)}));return out.slice(0,10)}
function install(){const G=window[GNAME];if(!G||typeof G.generate!=='function'||G.comprehensionOEDNAVersion===VERSION)return !!G&&G.comprehensionOEDNAVersion===VERSION;const original=G.generate;G.generate=function(options={}){const result=original.call(this,options);if(!result||!Array.isArray(result.paper))return result;const qs=build((options.seed||Date.now())^0x66aa7711);if(qs.length!==10)return result;const rest=result.paper.filter(q=>q&&q.section!=='comprehension');qs.forEach((q,i)=>{q.number=66+i;q.id='Q'+(66+i)});result.paper=rest.concat(qs);result.paper.forEach((q,i)=>{q.number=i+1;q.id='Q'+(i+1)});result.diagnostics=result.diagnostics||{};result.diagnostics.comprehensionOEDNA=VERSION;result.diagnostics.comprehensionOEPassageIds=[...new Set(qs.map(q=>q.passageSetId))];result.diagnostics.comprehensionOESkills=qs.map(q=>q.skill);result.ok=true;return result};G.comprehensionOEDNAVersion=VERSION;return true}
let tries=0;const timer=setInterval(()=>{if(install()||++tries>120)clearInterval(timer)},100);install();
})();
(function(){'use strict';const load=()=>{if(document.querySelector('script[data-aplus-final-qg]'))return;const s=document.createElement('script');s.src='prelim-psle-final-quality-gate-v1-20260918.js?v=20260918b';s.async=false;s.dataset.aplusFinalQg='1';document.head.appendChild(s)};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load()})();
